package browser

import (
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

// Disk management for the persistent Chrome profiles under the profile root:
//
//	<root>                      shared desktop profile
//	<root>-sessions/<id>[-N]    per-session fallback while <root> is busy
//	<root>-stores/<key>         per-store profile
//	<root>-stores/<key>-sessions/<id>[-N]
//
// Session profiles belong to one conversation and are removed with it. Caches
// are regenerated by Chrome, so they may be cleared from any profile that is
// not running; cookies, logins and extensions are never touched.

// diskCacheBytes caps Chrome's HTTP cache per profile; without it a long-lived
// profile grows its cache to gigabytes.
const diskCacheBytes = 100 << 20

// profileCacheDirs are regenerable cache directories inside a Chrome profile.
var profileCacheDirs = []string{
	filepath.Join("Default", "Cache"),
	filepath.Join("Default", "Code Cache"),
	filepath.Join("Default", "GPUCache"),
	filepath.Join("Default", "DawnGraphiteCache"),
	filepath.Join("Default", "DawnWebGPUCache"),
	"GrShaderCache",
	"GraphiteDawnCache",
	"ShaderCache",
}

func (s *Service) currentProfileRoot() string {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.profileRoot == "" {
		return ""
	}
	return filepath.Clean(s.profileRoot)
}

// profileParents returns every profile root: the shared root and each store.
func profileParents(root string) []string {
	parents := []string{root}
	entries, err := os.ReadDir(root + "-stores")
	if err != nil {
		return parents
	}
	for _, e := range entries {
		if e.IsDir() && !strings.HasSuffix(e.Name(), "-sessions") {
			parents = append(parents, filepath.Join(root+"-stores", e.Name()))
		}
	}
	return parents
}

// isSessionProfileName reports whether name is sessionID or sessionID-N, the
// only names window.go gives a session's fallback profile.
func isSessionProfileName(name, sessionID string) bool {
	if name == sessionID {
		return true
	}
	suffix, ok := strings.CutPrefix(name, sessionID+"-")
	if !ok || suffix == "" {
		return false
	}
	for _, c := range suffix {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func isRealDir(path string) bool {
	info, err := os.Lstat(path)
	return err == nil && info.IsDir() && info.Mode()&os.ModeSymlink == 0
}

func dirBytes(root string) int64 {
	var total int64
	_ = filepath.WalkDir(root, func(_ string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.Type().IsRegular() {
			if info, err := d.Info(); err == nil {
				total += info.Size()
			}
		}
		return nil
	})
	return total
}

// ForgetSession stops the session's Chrome processes and deletes its own
// fallback profiles. Shared and store profiles are kept. It returns the bytes
// removed.
func (s *Service) ForgetSession(sessionID string) int64 {
	sessionID = strings.TrimSpace(sessionID)
	if !sessionPattern.MatchString(sessionID) || sessionID == "default" {
		return 0
	}
	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		return 0
	}
	var victims, shared []*scope
	for key, sc := range s.scopes {
		if key.session == sessionID {
			victims = append(victims, sc)
			delete(s.scopes, key)
			delete(s.idleClosed, key)
		} else if sc != nil {
			shared = append(shared, sc)
		}
	}
	s.mu.Unlock()
	for _, sc := range shared {
		sc.forgetCallerSession(sessionID)
	}
	// Wait for any in-flight operation, then stop Chrome before its profile
	// directory disappears underneath it.
	for _, sc := range victims {
		sc.gate <- struct{}{}
		sc.dispose()
		<-sc.gate
	}

	var freed int64
	for _, path := range s.sessionProfileDirs(sessionID) {
		size := dirBytes(path)
		if os.RemoveAll(path) == nil {
			freed += size
		}
	}
	return freed
}

// sessionProfileDirs lists the session's own fallback profiles across every
// profile root. Symlinks and look-alike names are never included.
func (s *Service) sessionProfileDirs(sessionID string) []string {
	root := s.currentProfileRoot()
	if root == "" || !sessionPattern.MatchString(sessionID) || sessionID == "default" {
		return nil
	}
	var out []string
	for _, parent := range profileParents(root) {
		dir := parent + "-sessions"
		entries, err := os.ReadDir(dir)
		if err != nil {
			continue
		}
		for _, e := range entries {
			path := filepath.Join(dir, e.Name())
			if e.IsDir() && isSessionProfileName(e.Name(), sessionID) && isRealDir(path) {
				out = append(out, path)
			}
		}
	}
	return out
}

// SessionProfileBytes returns the disk used by the session's own profiles,
// which ForgetSession would remove.
func (s *Service) SessionProfileBytes(sessionID string) int64 {
	var total int64
	for _, path := range s.sessionProfileDirs(strings.TrimSpace(sessionID)) {
		total += dirBytes(path)
	}
	return total
}

// allProfiles lists every persistent profile directory, session ones included.
func allProfiles(root string) []string {
	var out []string
	for _, parent := range profileParents(root) {
		if isRealDir(parent) {
			out = append(out, parent)
		}
		entries, err := os.ReadDir(parent + "-sessions")
		if err != nil {
			continue
		}
		for _, e := range entries {
			if path := filepath.Join(parent+"-sessions", e.Name()); e.IsDir() && isRealDir(path) {
				out = append(out, path)
			}
		}
	}
	return out
}

// ProfileStorageBytes returns the disk used by all persistent profiles.
func (s *Service) ProfileStorageBytes() int64 {
	root := s.currentProfileRoot()
	if root == "" {
		return 0
	}
	var total int64
	for _, p := range allProfiles(root) {
		total += dirBytes(p)
	}
	return total
}

// profileInUse reports whether a Chrome may be running on profile: one this
// service started, or any other process holding Chromium's singleton lock.
func (s *Service) profileInUse(profile string) bool {
	s.mu.Lock()
	for _, sc := range s.scopes {
		if sc.browser != nil && sc.profile != "" && filepath.Clean(sc.profile) == profile {
			s.mu.Unlock()
			return true
		}
	}
	s.mu.Unlock()
	if isOSProfileLockHeld(profile) {
		return true
	}
	_, err := os.Lstat(filepath.Join(profile, "SingletonLock"))
	return err == nil
}

// ClearProfileCaches deletes regenerable caches from every profile that is
// not running and returns the bytes freed and how many profiles were skipped.
func (s *Service) ClearProfileCaches() (freed int64, skipped int) {
	root := s.currentProfileRoot()
	if root == "" {
		return 0, 0
	}
	for _, profile := range allProfiles(root) {
		if s.profileInUse(profile) {
			skipped++
			continue
		}
		for _, rel := range profileCacheDirs {
			path := filepath.Join(profile, rel)
			if !isRealDir(path) {
				continue
			}
			size := dirBytes(path)
			if os.RemoveAll(path) == nil {
				freed += size
			}
		}
	}
	return freed, skipped
}
